def parse_grid_block(text, label):
    m=re.search(re.escape(label)+r' \((\d+)x(\d+)\):\n((?:[0-9 ]+\n?)+)', text)
    if not m: raise ValueError(label)
    h,w=map(int,m.group(1,2))
    rows=[[int(x) for x in ln.split()] for ln in m.group(3).strip().splitlines()]
    assert len(rows)==h and all(len(r)==w for r in rows),(label,len(rows),[len(r) for r in rows])
    return rows
