def transform(grid, conn=4):
    h,w=len(grid),len(grid[0]); bg=grid[0][0]
    seen=set(); stack=[]
    for r in range(h):
        for c in (0,w-1):
            if grid[r][c]==bg: stack.append((r,c))
    for c in range(w):
        for r in (0,h-1):
            if grid[r][c]==bg: stack.append((r,c))
    dirs=[(-1,0),(1,0),(0,-1),(0,1)]
    if conn==8: dirs += [(-1,-1),(-1,1),(1,-1),(1,1)]
    while stack:
        r,c=stack.pop()
        if (r,c) in seen or grid[r][c]!=bg: continue
        seen.add((r,c))
        for dr,dc in dirs:
            nr,nc=r+dr,c+dc
            if 0<=nr<h and 0<=nc<w and (nr,nc) not in seen and grid[nr][nc]==bg: stack.append((nr,nc))
    return [[(bg if (r,c) in seen else 3 if grid[r][c]==bg else grid[r][c]) for c in range(w)] for r in range(h)]
